// Extract and validate input
const body = $input.first().json.body || $input.first().json;

const komoditas = body.komoditas || 'Cabai Merah';
const farmer_name = body.farmer_name || 'Petani Mitra AgriSensa';
const lokasi_lahan = body.lokasi_lahan || 'Jawa Barat';
const luas_ha = parseFloat(body.luas_ha || 0.5);
const volume_kg = parseFloat(body.volume_kg || 1000);
const varietas = body.varietas_benih || 'Unggul F1';
const grade = body.grade_kualitas || 'Grade A Super';

return [{
  json: {
    komoditas: komoditas,
    farmer_name: farmer_name,
    lokasi_lahan: lokasi_lahan,
    luas_ha: luas_ha,
    volume_kg: volume_kg,
    varietas_benih: varietas,
    grade_kualitas: grade,
    perlakuan_pupuk: body.perlakuan_pupuk || 'NPK Presisi + Organik Hayati',
    perlakuan_pestisida: body.perlakuan_pestisida || 'Pestisida Nabati',
    gps_coordinates: body.gps_coordinates || { lat: -6.8167, lon: 107.6167 },
    tanggal_panen: body.tanggal_panen || new Date().toISOString().split('T')[0],
    timestamp: new Date().toISOString()
  }
}];

